class Solution {
    public String smallestSubsequence(String s,int k,char letter,int repetition){
        int remainingLetter=0;
        for(char value:s.toCharArray())if(value==letter)remainingLetter++;
        StringBuilder stack=new StringBuilder();
        int usedLetter=0,n=s.length();
        for(int i=0;i<n;i++){
            char value=s.charAt(i);
            while(stack.length()>0&&stack.charAt(stack.length()-1)>value&&stack.length()+n-i>k&&(stack.charAt(stack.length()-1)!=letter||usedLetter-1+remainingLetter>=repetition)){
                if(stack.charAt(stack.length()-1)==letter)usedLetter--;
                stack.deleteCharAt(stack.length()-1);
            }
            if(stack.length()<k){
                if(value==letter){
                    stack.append(value);
                    usedLetter++;
                }else if(k-stack.length()>repetition-usedLetter)stack.append(value);
            }
            if(value==letter)remainingLetter--;
        }
        return stack.toString();
    }
}

