class Solution {
    public: string smallestSubsequence(string s,int k,char letter,int repetition){
        int remainingLetter=count(s.begin(),s.end(),letter),usedLetter=0,n=s.size();
        string stack;
        for(int i=0;i<n;++i){
            char value=s[i];
            while(!stack.empty()&&stack.back()>value&&(int)stack.size()+n-i>k&&(stack.back()!=letter||usedLetter-1+remainingLetter>=repetition)){
                if(stack.back()==letter)--usedLetter;
                stack.pop_back();
            }
            if((int)stack.size()<k){
                if(value==letter){
                    stack+=value;
                    ++usedLetter;
                }else if(k-(int)stack.size()>repetition-usedLetter)stack+=value;
            }
            if(value==letter)--remainingLetter;
        }
        return stack;
    }
};
